   FROM customer_accounts a
  WHERE ((a.organization_id = portal_payment_requests.organization_id) AND (a.customer_id = portal_payment_requests.customer_id) AND (a.auth_user_id = auth.uid()) AND (a.status = 'active'::text))))));
